// Diario Temperatura — Scriptable Home Screen / Lock Screen widget
// In Scriptable, set the widget's Parameter to the private key generated by the app.
const API_URL = "https://muuihmayqnvzugomfwlq.supabase.co/functions/v1/temperature-widget";
const APP_URL = "https://diario-temperatura-cloud.vercel.app/";
const TOKEN = String(args.widgetParameter || "").trim();
// Legacy anon key: public gateway key; widget token remains the actual user authentication.

const widget = new ListWidget();
widget.backgroundColor = new Color("#111827");
widget.setPadding(14, 14, 14, 14);
widget.url = APP_URL;

function text(parent, value, size, color, bold = false) {
  const t = parent.addText(String(value));
  t.textColor = new Color(color);
  t.font = bold ? Font.boldSystemFont(size) : Font.systemFont(size);
  t.lineLimit = 1;
  return t;
}
function elapsed(iso) {
  if (!iso || !Number.isFinite(new Date(iso).getTime())) return "—";
  const mins = Math.max(0, Math.floor((Date.now() - new Date(iso).getTime()) / 60000));
  const days = Math.floor(mins / 1440);
  const hours = Math.floor((mins % 1440) / 60);
  const rest = mins % 60;
  if (days) return days + "g " + hours + "h";
  if (hours) return hours + "h " + rest + "m";
  return rest + " min";
}
function clock(iso) {
  if (!iso || !Number.isFinite(new Date(iso).getTime())) return "Nessuna registrazione";
  return new Date(iso).toLocaleString("it-IT", { day:"2-digit", month:"2-digit", hour:"2-digit", minute:"2-digit" });
}
function timerRow(parent, name, iso, dot) {
  const row = parent.addStack();
  row.centerAlignContent();
  const marker = row.addText("●");
  marker.textColor = new Color(dot);
  marker.font = Font.boldSystemFont(9);
  row.addSpacer(5);
  const label = row.addText(name);
  label.textColor = new Color("#D1D5DB");
  label.font = Font.mediumSystemFont(10);
  row.addSpacer();
  const value = row.addText(iso && Number.isFinite(new Date(iso).getTime()) ? clock(iso) + " · " + elapsed(iso) : "—");
  value.textColor = new Color("#FFFFFF");
  value.font = Font.semiboldSystemFont(10);
}
function errorWidget(message) {
  text(widget, "DIARIO TEMPERATURA", 10, "#9CA3AF", true);
  widget.addSpacer(8);
  text(widget, "Widget non configurato", 16, "#FFFFFF", true);
  widget.addSpacer(4);
  text(widget, message, 11, "#D1D5DB");
  widget.addSpacer();
  text(widget, "Tocca per aprire l'app", 10, "#9CA3AF");
}
try {
  if (!TOKEN) {
    errorWidget("Imposta la chiave nel campo Parameter del widget Scriptable.");
  } else {
    const req = new Request(API_URL);
    req.method = "GET";
    req.headers = { "Authorization": "Bearer " + TOKEN, "apikey": "sb_publishable_QLIN1H0b8iNL7Rekw9lZHA_KayB6Mcd" };
    req.timeoutInterval = 15;
    const data = await req.loadJSON();
    if (data.error) throw new Error(data.error);

    text(widget, "DIARIO TEMPERATURA", 10, "#9CA3AF", true);
    widget.addSpacer(8);
    const latest = data.latest;
    if (latest) {
      const temp = text(widget, Number(latest.temperature).toFixed(1) + "°", 34, "#FFFFFF", true);
      temp.minimumScaleFactor = 0.7;
      text(widget, "Ultima temperatura · " + clock(latest.measured_at), 10, "#D1D5DB");
      if (latest.medication && latest.medication !== "Nessuno") {
        widget.addSpacer(3);
        text(widget, "Farmaco: " + latest.medication, 10, "#FBBF24");
      }
    } else {
      text(widget, "Nessuna temperatura", 17, "#FFFFFF", true);
    }

    if (config.widgetFamily !== "small" && config.widgetFamily !== "accessoryCircular" && config.widgetFamily !== "accessoryInline") {
      widget.addSpacer(8);
      const divider = widget.addText("────────────────────────");
      divider.textColor = new Color("#374151");
      divider.font = Font.systemFont(8);
      widget.addSpacer(5);
      timerRow(widget, "Nurofen", data.timers?.Nurofen, "#60A5FA");
      widget.addSpacer(4);
      timerRow(widget, "Tachipirina", data.timers?.Tachipirina, "#FBBF24");
      widget.addSpacer(4);
      timerRow(widget, "Antibiotico", data.timers?.Antibiotico, "#C084FC");
    } else if (config.widgetFamily === "accessoryCircular") {
      widget.addSpacer(4);
      text(widget, latest ? Number(latest.temperature).toFixed(1) + "°" : "—", 17, "#FFFFFF", true);
    }
    widget.addSpacer();
    text(widget, "Aggiornato " + new Date(data.generatedAt).toLocaleTimeString("it-IT", {hour:"2-digit",minute:"2-digit"}), 9, "#9CA3AF");
  }
} catch (e) {
  errorWidget("Errore di aggiornamento. Controlla la connessione o riapri Scriptable.");
}
widget.refreshAfterDate = new Date(Date.now() + 15 * 60 * 1000);
if (config.runsInWidget) {
  Script.setWidget(widget);
} else {
  await widget.presentMedium();
}
Script.complete();
